param([string]$Name='client-a',[switch]$WithOriginals,[switch]$WithProjectE)
$ErrorActionPreference='Stop';$taskRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));if($Name -notmatch '^client-[a-zA-Z0-9.-]+$'){throw 'Invalid test name.'};$taskRelative=".toolchain/accessory-tests/$Name";$taskPath=Join-Path $taskRoot $taskRelative;if(Test-Path -LiteralPath $taskPath){throw 'Use a fresh disposable test directory.'};New-Item -ItemType Directory -Path (Join-Path $taskPath 'mods/1.7.10') -Force | Out-Null
Copy-Item -LiteralPath (Join-Path $taskRoot '.toolchain/nei/CodeChickenLib-1.7.10-1.1.3.140-dev.jar') -Destination (Join-Path $taskPath 'mods/1.7.10')
foreach($taskName in @('CodeChickenCore-1.7.10-1.0.7.47-dev.jar','NotEnoughItems-1.7.10-1.0.5.120-dev.jar')){Copy-Item -LiteralPath (Join-Path $taskRoot ".toolchain/nei/$taskName") -Destination (Join-Path $taskPath 'mods')}
if($WithOriginals -or $WithProjectE){Copy-Item -LiteralPath (Join-Path $taskRoot '.toolchain/accessories-upstream/ProjectE-dev.jar') -Destination (Join-Path $taskPath 'mods')}
if($WithOriginals){Copy-Item -LiteralPath (Join-Path $taskRoot '.toolchain/accessories-upstream/Baublelicious-dev.jar') -Destination (Join-Path $taskPath 'mods')}
& (Join-Path $PSScriptRoot 'build.ps1') -Tasks @('runClient','-PtestClient','-PaccessoryClient',"-PtestRunDir=$taskRelative") *> (Join-Path $taskRoot ".toolchain/accessory-tests/$Name.log")
if($LASTEXITCODE -ne 0){Get-Content -LiteralPath (Join-Path $taskRoot ".toolchain/accessory-tests/$Name.log") -Tail 45;throw 'Accessory client failed.'};Get-Content -LiteralPath (Join-Path $taskPath 'accessories-client.txt');if((Get-Content -LiteralPath (Join-Path $taskPath 'accessories-client.txt'))[-1] -ne 'Failed: 0'){throw 'Accessory graphical checks failed.'}
